-- Темы 14–16: исправлены странности в 16 вопросах (39 исправлений), прежние версии в question_archive (миграция 117), ключи не меняются.
-- Источник: scripts/questions/118_oddities_topics14_16.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', NULL, NULL, NULL, 'Какая цепочка WAL необходима, чтобы восстановить согласованное состояние горячей базовой копии основного сервера?'),
        ('question', 'Когда сегмент журнала попадает в файловый архив?', NULL, NULL, NULL, 'При настроенной файловой архивации какое событие делает сегмент WAL готовым к передаче в архив?'),
        ('question', 'Допишите команду archive_command, чтобы сегмент копировался в архив под своим именем:
```
archive_command = ''cp %p /mnt/archive/___''
```', NULL, NULL, NULL, 'Допишите одну и ту же подстановку в оба пропуска, чтобы копировать сегмент под его именем, отказываясь перезаписывать существующий файл:
```
archive_command = ''test ! -f /mnt/archive/___ && cp %p /mnt/archive/___''
```
```
archive_command = ''cp %p /mnt/archive/___''
```'),
        ('question', 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', NULL, NULL, NULL, 'При synchronous_commit = on основной сервер получил подтверждение от синхронной реплики и вернул успешный COMMIT. Приложение открывает новое соединение к этой реплике и выполняет SELECT. Гарантировано ли, что запрос увидит изменения этой транзакции?'),
        ('question', 'Какие два источника журнальных записей могут конфликтовать с запросом на реплике?', NULL, NULL, NULL, 'Какие действия на основном сервере могут приводить к конфликтам воспроизведения WAL с SELECT на физической реплике?'),
        ('question', 'Что позволяет сгладить проблему с долгими транзакциями при логической репликации?', NULL, NULL, NULL, 'Крупная транзакция на издателе ещё не завершилась. Какая настройка позволяет передавать её изменения подписчику частями до COMMIT?'),
        ('question', 'Как избежать конфликтов уникальных ключей из-за того, что значения последовательностей не реплицируются?', NULL, NULL, NULL, 'При двунаправленной логической репликации оба узла вставляют строки с ключами из локальных последовательностей. Как уменьшить риск конфликтов первичного ключа?'),
        ('question', 'Почему для обновления основной версии без прерывания обслуживания не подходит физическая репликация?', NULL, NULL, NULL, 'Почему физическая репликация не подходит для перехода на новую основную версию с минимальным простоем?'),
        ('option', 'Какое преимущество у логической резервной копии?', 'Её можно восстановить на любой момент после выгрузки', NULL, 'Восстановить можно только на момент выгрузки: журнала для продвижения дальше в логической копии нет.', 'Дамп отражает свой снимок данных; применять WAL для продвижения к более позднему состоянию к нему нельзя.'),
        ('option', 'Какое преимущество у логической резервной копии?', 'Её восстанавливают быстрее, чем физическую копию', NULL, 'Восстановление медленное: выполняются все команды, индексы строятся заново.', 'Выполняются SQL-команды и заново строятся индексы. На больших базах это обычно дольше физического восстановления, но итог зависит от данных, WAL и ресурсов.'),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', '\copy работает быстрее COPY: данные идут в обход клиента', NULL, 'Наоборот, при \copy данные идут через клиента psql, это не быстрее.', 'При \copy данные проходят через psql, утверждение об обходе клиента неверно. Скорость зависит и от расположения файлов, сети и дисков.'),
        ('explanation', 'Из какого шаблона рекомендуется создавать базу для восстановления из pg_dump?', NULL, NULL, 'Изменения template1 тоже попадают в копию и вызвали бы конфликты.', 'Если исходная база унаследовала добавленные в template1 объекты, pg_dump включает их в дамп. Создание базы восстановления из изменённого template1 может продублировать их и вызвать конфликты; template0 исключает такие добавления.'),
        ('option', 'Какая совместимость серверов нужна для физической репликации?', 'Двоичная: та же платформа и основная версия', NULL, 'Записи применяются механически, без понимания смысла.', 'Для физической репликации требуются та же основная версия и совместимая платформа; совместимости сетевого протокола недостаточно.'),
        ('explanation', 'Какая совместимость серверов нужна для физической репликации?', NULL, NULL, 'Записи применяются механически, без понимания смысла изменений.', 'Физическая репликация воспроизводит WAL над внутренними структурами данных; нужны совместимые форматы WAL и файлов.'),
        ('option', 'Что даёт включение hot_standby_feedback?', 'Очистка не трогает версии, нужные реплике', 'Очистка учитывает горизонт запросов реплики', 'Пока работает соединение, реплика сообщает мастеру горизонт своих запросов, и очистка на мастере не удаляет версии, нужные этим запросам.', 'Очистка учитывает переданный горизонт. Обратная связь не защищает от конфликтов ACCESS EXCLUSIVE и не даёт безусловной защиты при потере соединения.'),
        ('explanation', 'Что даёт включение hot_standby_feedback?', NULL, NULL, 'Эффект такой, как если бы запросы реплики выполнялись на мастере.', 'Обратная связь сообщает горизонт запросов реплики и уменьшает конфликты очистки. Она может увеличить объём старых версий на основном сервере и не устраняет все причины отмены запросов.'),
        ('option', 'На какой момент можно восстановить данные из обычной логической копии?', 'Только на момент, когда копия была снята', 'На момент снимка, использованного pg_dump', 'Логическая копия не содержит журнала, по которому можно было бы продвинуться дальше.', 'Это снимок pg_dump, а не состояние базы в момент окончания выгрузки; WAL для продвижения вперёд дамп не содержит.'),
        ('option', 'На какой момент можно восстановить данные из обычной логической копии?', 'На момент сбоя сервера', NULL, 'Это возможно только при непрерывной архивации журналов.', 'Обычный логический дамп не включает более поздние изменения. После сбоя возможно и обычное физическое восстановление по локальному WAL, без архива.'),
        ('option', 'На какой момент можно восстановить данные из обычной логической копии?', 'На любой момент после снятия копии', NULL, 'Для этого нужен архив журналов предзаписи, то есть физическое копирование.', 'Для PITR нужна физическая базовая копия и непрерывная цепочка WAL до целевой точки; к логическому дампу такой WAL не применяется.'),
        ('option', 'Какая цепочка WAL необходима, чтобы восстановить согласованное состояние горячей базовой копии основного сервера?', 'Как минимум журналы за время копирования файлов', 'От REDO начальной контрольной точки до конца копии', 'Копия получается несогласованной, и согласованность восстанавливается по журналам.', 'Нужна непрерывная цепочка от REDO начальной контрольной точки до записи конца резервного копирования; для PITR — и далее до целевой точки.'),
        ('option', 'Какая цепочка WAL необходима, чтобы восстановить согласованное состояние горячей базовой копии основного сервера?', 'Последний сегмент журнала перед началом копирования', NULL, 'Нужны все записи за время копирования.', 'Один сегмент перед копированием не заменяет необходимую непрерывную цепочку WAL.'),
        ('option', 'Какая цепочка WAL необходима, чтобы восстановить согласованное состояние горячей базовой копии основного сервера?', 'Журналы, записанные после окончания копирования', NULL, 'Нужны записи за время копирования, начиная с контрольной точки.', 'WAL после окончания копии не заменяет более ранние записи, необходимые для согласования скопированных файлов.'),
        ('option', 'Зачем при резервном копировании по протоколу репликации используется слот репликации?', 'Чтобы сервер не удалил сегменты WAL, пока клиент не получил их', 'Чтобы WAL сохранялся до подтверждения сброса клиентом', 'Слот помнит, до какой позиции клиент получил журнал, и удерживает ещё не полученные сегменты.', 'Получение данных и их надёжное сохранение — разные этапы. При конечном max_slot_wal_keep_size нужный WAL всё же может быть удалён, если клиент сильно отстанет.'),
        ('explanation', 'Зачем при резервном копировании по протоколу репликации используется слот репликации?', NULL, NULL, 'Слот помнит, какая запись была считана последней.', 'Физический слот удерживает WAL по restart_lsn; эта позиция продвигается по подтверждённому flush клиента.'),
        ('option', 'При настроенной файловой архивации какое событие делает сегмент WAL готовым к передаче в архив?', 'Когда сервер переключится на следующий сегмент', NULL, 'Архивируется завершённый сегмент, а завершить его сервер может и до заполнения. Текущий сегмент в архив не попадает, отсюда задержки.', 'Архивируется завершённый сегмент, а завершить его сервер может и до заполнения. Текущий сегмент в архив не попадает; завершённый копируется асинхронно и может ждать своей очереди.'),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Записи текущего сегмента WAL, не попавшего в архив', 'Записи всех сегментов WAL, ещё не попавших в архив', 'Если его нельзя скопировать вручную, он теряется.', 'Если исходный WAL недоступен, теряются незаархивированные записи; это может быть несколько сегментов, а не только текущий.'),
        ('explanation', 'Допишите одну и ту же подстановку в оба пропуска, чтобы копировать сегмент под его именем, отказываясь перезаписывать существующий файл:
```
archive_command = ''test ! -f /mnt/archive/___ && cp %p /mnt/archive/___''
```
```
archive_command = ''cp %p /mnt/archive/___''
```', NULL, NULL, '%f подставляет имя архивируемого файла без каталога, поэтому получается путь /mnt/archive/имя_файла.', 'В обоих пропусках %f. Проверка test предотвращает перезапись; повторную доставку одинакового, уже надёжно сохранённого сегмента в рабочем архиваторе обрабатывают отдельно.'),
        ('option', 'При synchronous_commit = on основной сервер получил подтверждение от синхронной реплики и вернул успешный COMMIT. Приложение открывает новое соединение к этой реплике и выполняет SELECT. Гарантировано ли, что запрос увидит изменения этой транзакции?', 'Да, при синхронной репликации всё согласовано', 'Да, подтверждения синхронной реплики достаточно', 'Согласованность между серверами не гарантируется даже в этом случае.', 'Подтверждён сброс WAL на диск, а не завершение его воспроизведения.'),
        ('option', 'При synchronous_commit = on основной сервер получил подтверждение от синхронной реплики и вернул успешный COMMIT. Приложение открывает новое соединение к этой реплике и выполняет SELECT. Гарантировано ли, что запрос увидит изменения этой транзакции?', 'Нет, даже синхронная репликация этого не гарантирует', 'Нет, при таком режиме фиксации гарантии нет', 'Даже при синхронной репликации можно получить устаревшие данные или такие, которых ещё не видно на основном сервере. Режим remote_apply ждёт применения на синхронных репликах, но и он не делает чтения с разных серверов единым снимком.', 'Режим remote_apply ждёт применения на подтверждающей синхронной реплике и обеспечивает видимость изменений для новых снимков на ней.'),
        ('option', 'При synchronous_commit = on основной сервер получил подтверждение от синхронной реплики и вернул успешный COMMIT. Приложение открывает новое соединение к этой реплике и выполняет SELECT. Гарантировано ли, что запрос увидит изменения этой транзакции?', 'Да, если используется каскадная репликация', 'Да, если настроена каскадная репликация', 'Для каскада это тем более не гарантируется.', 'Каскад сам по себе не гарантирует применения WAL к моменту чтения.'),
        ('option', 'При synchronous_commit = on основной сервер получил подтверждение от синхронной реплики и вернул успешный COMMIT. Приложение открывает новое соединение к этой реплике и выполняет SELECT. Гарантировано ли, что запрос увидит изменения этой транзакции?', 'Да, если включена обратная связь hot_standby_feedback', 'Да, если включён hot_standby_feedback', 'Обратная связь влияет на очистку и не обеспечивает согласованность чтения.', 'Обратная связь влияет на очистку, а не на момент применения WAL.'),
        ('explanation', 'При synchronous_commit = on основной сервер получил подтверждение от синхронной реплики и вернул успешный COMMIT. Приложение открывает новое соединение к этой реплике и выполняет SELECT. Гарантировано ли, что запрос увидит изменения этой транзакции?', NULL, NULL, 'Разные серверы могут находиться на разных позициях применения WAL; обычное синхронное подтверждение не делает произвольные чтения между серверами единым снимком.', 'Режим on ждёт сохранения WAL на реплике, но не его применения; чтение может вернуть состояние до этой транзакции.'),
        ('option', 'Какие действия на основном сервере могут приводить к конфликтам воспроизведения WAL с SELECT на физической реплике?', 'Исключительные блокировки на основном сервере', 'Блокировка ACCESS EXCLUSIVE читаемой таблицы', 'Например, блокировка ACCESS EXCLUSIVE таблицы, которую читает запрос на реплике.', 'Воспроизведение ACCESS EXCLUSIVE требует конфликтующей блокировки на реплике; режим EXCLUSIVE сам по себе не конфликтует с ACCESS SHARE обычного SELECT.'),
        ('explanation', 'Крупная транзакция на издателе ещё не завершилась. Какая настройка позволяет передавать её изменения подписчику частями до COMMIT?', NULL, NULL, 'Изменения при этом либо накапливаются во временном файле, либо сразу применяются.', 'При streaming = on подписчик сохраняет части во временные файлы и применяет после COMMIT издателя. При streaming = parallel PostgreSQL 16 может применять их до COMMIT в параллельных рабочих процессах. Изменения строк становятся видны другим транзакциям после локальной фиксации.'),
        ('option', 'При двунаправленной логической репликации оба узла вставляют строки с ключами из локальных последовательностей. Как уменьшить риск конфликтов первичного ключа?', 'Включить репликацию последовательностей параметром публикации', 'Включить передачу SEQUENCE в параметрах публикации', 'В PostgreSQL 16 значения последовательностей не реплицируются.', 'В PostgreSQL 16 состояние последовательностей не передаётся параметрами публикации.'),
        ('option', 'При двунаправленной логической репликации оба узла вставляют строки с ключами из локальных последовательностей. Как уменьшить риск конфликтов первичного ключа?', 'Выполнить TRUNCATE на подписчике', 'Задать одинаковый START у обеих последовательностей', 'Это удалит данные, но не решит проблему.', 'Одинаковый START даёт обеим последовательностям одни и те же значения: потоки генерации не разделяются, и совпадения неизбежны.'),
        ('option', 'При двунаправленной логической репликации оба узла вставляют строки с ключами из локальных последовательностей. Как уменьшить риск конфликтов первичного ключа?', 'Выделить серверам разные диапазоны значений или использовать UUID', 'Развести диапазоны ключей или использовать UUID', 'Так серверы не сгенерируют одинаковые ключи.', 'Непересекающиеся диапазоны предотвращают пересечение ключей при соблюдении настройки; подходящие UUID делают случайное совпадение крайне маловероятным.'),
        ('option', 'При двунаправленной логической репликации оба узла вставляют строки с ключами из локальных последовательностей. Как уменьшить риск конфликтов первичного ключа?', 'Использовать wal_level = minimal', 'Выставить REPLICA IDENTITY FULL на обеих таблицах', 'Этот уровень логическую репликацию не поддерживает.', 'FULL задаёт идентификацию строк для UPDATE и DELETE, но не меняет генерацию ключей.'),
        ('option', 'Почему физическая репликация не подходит для перехода на новую основную версию с минимальным простоем?', 'Между основными версиями нет двоичной совместимости', NULL, 'Физическая репликация применяет журнал к страницам механически.', 'Потоковая физическая репликация между основными версиями не поддерживается: форматы WAL и внутренних структур могут различаться.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
